class Solution1:
    def removeDuplicates(self,s,k):
        stack=[];c=s[0];stack.append(c);count=1
        for i in range(1,len(s)):
            if(s[i]==c):
                count+=1;stack.append(s[i])
                if(count==k):
                    while(not len(stack)==0 and stack[-1]==c):
                        stack.pop()
                    count=0
                    if(not len(stack)==0):
                        c=stack[-1]
                        while(not len(stack)==0 and c==stack[-1]):
                            count+=1;stack.pop()
                        tmp=count
                        while(tmp>0):
                            stack.append(c);tmp-=1
            else:
                c=s[i];stack.append(s[i]);count=1
        sb=''.join(reversed(stack))
        return sb

class Solution2:
    def removeDuplicates(self,s,k):
        sb='';dupCount=0
        for i in range(len(s)):
            if(len(sb)!=0 and sb[-1]==s[i]):
                dupCount+=1
            else:
                dupCount=1
            sb+=s[i]
            if(dupCount==k):
                sb=sb[:-k]
                if(i+1<len(s)):dupCount=0
                j=len(sb)-1
                while(j>=0):
                    if(sb[j]==s[i+1]):
                        dupCount+=1
                    else:
                        break
                    j-=1
        return sb

